module StoneGame(\n    input [3:0] n,\n    input [31:0] a0,\n    input [31:0] a1,\n    input [31:0] a2,\n    input [31:0] a3,\n    input [31:0] a4,\n    input [31:0] a5,\n    input [31:0] a6,\n    input [31:0] a7,\n    output reg win\n);\n    \n    wire [31:0] arr [0:7];\n    assign arr[0] = a0;\n    assign arr[1] = a1;\n    assign arr[2] = a2;\n    assign arr[3] = a3;\n    assign arr[4] = a4;\n    assign arr[5] = a5;\n    assign arr[6] = a6;\n    assign arr[7] = a7;\n    \n    reg [31:0] temp [0:7];\n    integer i, j, k;\n    reg [31:0] swap;\n    reg [2:0] dup_count;\n    reg [31:0] dup_value;\n    reg triple;\n    reg lose_condition;\n    reg found_dup_value_minus_one;\n    reg [31:0] sum_val;\n    reg [31:0] base;\n    reg [31:0] S;\n    \n    always @(*) begin\n        for (i = 0; i < 8; i = i + 1) begin\n            temp[i] = (i < n) ? arr[i] : 32'hFFFF_FFFF;\n        end\n        \n        for (i = 0; i < 8; i = i + 1) begin\n            for (j = 0; j < 7 - i; j = j + 1) begin\n                if (temp[j] > temp[j+1]) begin\n                    swap = temp[j];\n                    temp[j] = temp[j+1];\n                    temp[j+1] = swap;\n                end\n            end\n        end\n        \n        dup_count = 3'd0;\n        dup_value = 32'd0;\n        triple = 1'b0;\n        lose_condition = 1'b0;\n        \n        for (i = 0; i < 7; i = i + 1) begin\n            if (i < n && (i+1) < n) begin\n                if (temp[i] == temp[i+1]) begin\n                    dup_count = dup_count + 3'd1;\n                    dup_value = temp[i];\n                    if ((i+2) < n && temp[i] == temp[i+2])\n                        triple = 1'b1;\n                end\n            end\n        end\n        \n        if (triple || (dup_count >= 3'd2)) begin\n            lose_condition = 1'b1;\n        end else if (dup_count == 3'd1) begin\n            if (dup_value == 32'd0) begin\n                lose_condition = 1'b1;\n            end else begin\n                found_dup_value_minus_one = 1'b0;\n                for (k = 0; k < n; k = k + 1) begin\n                    if (temp[k] == (dup_value - 32'd1))\n                        found_dup_value_minus_one = 1'b1;\n                end\n                lose_condition = found_dup_value_minus_one;\n            end\n        end\n        \n        sum_val = 32'd0;\n        for (i = 0; i < n; i = i + 1) begin\n            sum_val = sum_val + temp[i];\n        end\n        base = (n * (n - 4'd1)) >> 1;\n        S = sum_val - base;\n        \n        win = lose_condition ? 1'b0 : S[0];\n    end\nendmodule